-- V2's second unnamed CHECK is the state constraint generated by MySQL.
ALTER TABLE customer_order DROP CHECK customer_order_chk_2;
ALTER TABLE customer_order ADD CONSTRAINT chk_customer_order_status
    CHECK (status IN ('PREPARING','PENDING_PAYMENT','PAYMENT_PROCESSING','ABORTING','REJECTED','CANCELED','EXPIRED','RECONCILIATION_REQUIRED'));

CREATE TABLE order_payment_attempt (
    order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    payment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    amount BIGINT NOT NULL,
    currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    reservation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    expires_at TIMESTAMP(6) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    FOREIGN KEY (order_id) REFERENCES customer_order(id),
    CHECK (amount >= 0), CHECK (currency = 'KRW')
) ENGINE=InnoDB;
